<template><el-card><template #header><div class="header"><strong>套餐管理</strong><el-button type="primary" @click="openPackage()">新增套餐</el-button></div></template><el-table :data="packages" @row-click="selectPackage"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="description" label="说明"/><el-table-column label="状态"><template #default="s">{{ formatPortalStatus(s.row.status) }}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click.stop="openPackage(s.row)">编辑</el-button></template></el-table-column></el-table></el-card>
<el-card class="versions"><template #header><div class="header"><strong>套餐版本 {{ selectedPackage?.name||'' }}</strong><el-button :disabled="!selectedPackage" type="primary" @click="versionDialog=true">新增版本</el-button></div></template><el-table :data="versions"><el-table-column prop="versionNo" label="版本"/><el-table-column label="发布状态"><template #default="s">{{ formatPortalPublishStatus(s.row.publishStatus) }}</template></el-table-column><el-table-column prop="defaultUserLimit" label="默认用户数"/><el-table-column prop="changeNote" label="变更说明"/><el-table-column label="资源数"><template #default="s">{{s.row.resourceIds.length}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.publishStatus==='DRAFT'" link type="primary" @click="publish(s.row.id)">发布</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="packageDialog" title="套餐"><el-form label-width="90px"><el-form-item label="编码"><el-input v-model="packageForm.code" :disabled="!!editingId"/></el-form-item><el-form-item label="名称"><el-input v-model="packageForm.name"/></el-form-item><el-form-item label="说明"><el-input v-model="packageForm.description"/></el-form-item><el-form-item label="状态"><el-select v-model="packageForm.status"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></el-form><template #footer><el-button @click="packageDialog=false">取消</el-button><el-button type="primary" @click="savePackage">保存</el-button></template></el-dialog>
<el-dialog v-model="versionDialog" title="套餐版本"><el-form label-width="110px"><el-form-item label="版本号"><el-input-number v-model="versionForm.versionNo" :min="1"/></el-form-item><el-form-item label="用户上限"><el-input-number v-model="versionForm.defaultUserLimit" :min="1"/></el-form-item><el-form-item label="变更说明"><el-input v-model="versionForm.changeNote"/></el-form-item><el-form-item label="包含资源"><el-select v-model="versionForm.resourceIds" multiple filterable style="width:100%"><el-option v-for="r in resources" :key="r.id" :label="`${r.displayName} (${r.code})`" :value="r.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="versionDialog=false">取消</el-button><el-button type="primary" @click="saveVersion">保存草稿</el-button></template></el-dialog></template>
<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{apiClient}from'@/api';import type{ApplicationRecord,PackageRecord,PackageVersionRecord,ResourceRecord}from'@/types/management';import{formatPortalPublishStatus,formatPortalStatus}from'@/utils/portal-labels';const packages=ref<PackageRecord[]>([]),versions=ref<PackageVersionRecord[]>([]),resources=ref<ResourceRecord[]>([]);const selectedPackage=ref<PackageRecord|null>(null),packageDialog=ref(false),versionDialog=ref(false),editingId=ref('');const packageForm=reactive({code:'',name:'',description:'',status:'ACTIVE',version:0});const versionForm=reactive({versionNo:1,defaultUserLimit:100,changeNote:'',resourceIds:[]as string[]});async function load(){packages.value=(await apiClient.get('/management/platform/packages'))as PackageRecord[];const apps=(await apiClient.get('/management/platform/applications'))as ApplicationRecord[];resources.value=(await Promise.all(apps.filter(a=>a.scope==='TENANT').map(a=>apiClient.get(`/management/platform/applications/${a.id}/resources`)as Promise<ResourceRecord[]>))).flat()}async function selectPackage(row:PackageRecord){selectedPackage.value=row;versions.value=(await apiClient.get(`/management/platform/packages/${row.id}/versions`))as PackageVersionRecord[]}function openPackage(row?:PackageRecord){editingId.value=row?.id||'';Object.assign(packageForm,row||{code:'',name:'',description:'',status:'ACTIVE',version:0});packageDialog.value=true}async function savePackage(){if(editingId.value)await apiClient.put(`/management/platform/packages/${editingId.value}`,packageForm);else await apiClient.post('/management/platform/packages',packageForm);packageDialog.value=false;await load()}async function saveVersion(){if(!selectedPackage.value)return;await apiClient.post(`/management/platform/packages/${selectedPackage.value.id}/versions`,versionForm);versionDialog.value=false;await selectPackage(selectedPackage.value)}async function publish(id:string){await apiClient.post(`/management/platform/package-versions/${id}/publish`);ElMessage.success('套餐版本已发布');if(selectedPackage.value)await selectPackage(selectedPackage.value)}onMounted(()=>{void load()})
</script><style scoped>.header{display:flex;justify-content:space-between;align-items:center}.versions{margin-top:20px}</style>
